(function(){
const $=id=>document.getElementById(id);if(!$('railMode'))return;
let active=false,layer=null,lastJourneys=[];
const favoritesKey='lapan.rail.favorites.v1';
// Official static GTFS map layer, generated by scripts/update-official-gtfs.py.
// No fabricated station coordinates or route geometry are shown.
let gtfsOverlay=null,gtfsDataset=null;
const gtfsPanel=document.createElement('section');
gtfsPanel.className='rail-gtfs-layer';
gtfsPanel.style.cssText='padding:12px;margin:10px 0;border:1px solid #dbe8d8;border-radius:12px;background:#f5faf2';
gtfsPanel.innerHTML='<label style="display:flex;align-items:center;gap:9px;font-weight:700"><input id="gtfsMapToggle" type="checkbox"> Show official GTFS lines & stations on map</label><small id="gtfsMapStatus" style="display:block;margin-top:7px;color:#53665b">GTFS Static · KTMB, Rapid Rail, Rapid Bus. Data updated through GitHub Actions.</small>';
$('railPanel').prepend(gtfsPanel);
document.querySelector('#gtfsMapToggle').addEventListener('change',async function(){
 const status=document.querySelector('#gtfsMapStatus');
 if(!this.checked){if(gtfsOverlay&&window.LapanMap){window.LapanMap.removeLayer(gtfsOverlay);gtfsOverlay=null}status.textContent='GTFS overlay hidden.';return}
 if(!window.LapanMap||typeof L==='undefined'){this.checked=false;status.textContent='Map is not ready.';return}
 status.textContent='Loading official GTFS map data…';
 try{
  if(!gtfsDataset){const r=await fetch('/official-gtfs-map.json',{cache:'no-cache'});if(!r.ok)throw Error('Official GTFS map data unavailable');gtfsDataset=await r.json()}
  const feeds=Object.entries(gtfsDataset.feeds||{});
  if(!feeds.length)throw Error('GTFS dataset has not been imported. Run the GitHub Actions GTFS refresh workflow after uploading to GitHub.');
  gtfsOverlay=L.layerGroup();
  let lineCount=0,stationCount=0,schematicCount=0;
  for(const [feedId,feed] of feeds){
   for(const line of feed.lines||[]){
    if(!Array.isArray(line.coordinates)||line.coordinates.length<2)continue;
    const coords=line.coordinates.filter(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite)).map(p=>[p[1],p[0]]);
    if(coords.length<2)continue;
    const isSchematic=line.geometrySource!=='gtfs-shapes';if(isSchematic)schematicCount++;
    const color=/^[0-9a-f]{6}$/i.test(line.color||'')?'#'+line.color:'#2176ae';
    L.polyline(coords,{color,weight:3,opacity:.7,dashArray:isSchematic?'5 7':undefined})
      .bindPopup(document.createTextNode(line.name+' · '+feedId+(isSchematic?' · schematic connection':' · GTFS shape')).textContent)
      .addTo(gtfsOverlay);
    lineCount++;
   }
   // Render stations only at closer zoom levels to avoid clutter on mobile.
   for(const st of feed.stations||[]){
    const p=st.coordinates;
    if(!Array.isArray(p)||p.length!==2||!p.every(Number.isFinite))continue;
    const marker=L.circleMarker([p[1],p[0]],{radius:3,weight:1,color:'#fff',fillColor:'#114b3e',fillOpacity:.85});
    marker.bindTooltip(st.name+' · '+feedId,{direction:'top'});
    marker.addTo(gtfsOverlay);stationCount++;
   }
  }
  gtfsOverlay.addTo(window.LapanMap);
  status.textContent=`${lineCount} GTFS line shapes · ${stationCount} station points · ${schematicCount} schematic lines · Updated ${gtfsDataset.generatedAt?new Date(gtfsDataset.generatedAt).toLocaleDateString():'unknown'}. Static schedule/geography only.`;
 }catch(e){this.checked=false;if(gtfsOverlay&&window.LapanMap)window.LapanMap.removeLayer(gtfsOverlay);gtfsOverlay=null;status.textContent=e.message||'GTFS overlay unavailable'}
});

const readFavorites=()=>{try{return JSON.parse(localStorage.getItem(favoritesKey)||'[]')}catch{return []}};
const saveFavorites=items=>{try{localStorage.setItem(favoritesKey,JSON.stringify(items.slice(0,12)))}catch{}};
function renderFavorites(){const target=$('railFavorites');target.replaceChildren();readFavorites().forEach((item,index)=>{const row=document.createElement('div');row.className='rail-favorite';const go=document.createElement('button');go.type='button';go.className='link';go.textContent=item.from+' → '+item.to;go.onclick=()=>{$('origin').value=item.from;$('destination').value=item.to;$('railDate').value=item.date;$('railTime').value=item.time;mode(true)};const del=document.createElement('button');del.type='button';del.className='link';del.textContent='Remove';del.onclick=()=>{saveFavorites(readFavorites().filter((_,i)=>i!==index));renderFavorites()};row.append(go,del);target.append(row)})}
function tripInputs(){return {from:$('origin').value.trim(),to:$('destination').value.trim(),date:$('railDate').value,time:$('railTime').value}}
$('railSave').onclick=()=>{const item=tripInputs();if(!item.from||!item.to){$('railStatus').textContent='Choose both stations before saving.';return}saveFavorites([item,...readFavorites().filter(x=>x.from!==item.from||x.to!==item.to)]);renderFavorites();$('railStatus').textContent='Journey saved on this device.'};
$('railShare').onclick=async()=>{const item=tripInputs();if(!item.from||!item.to){$('railStatus').textContent='Choose both stations before sharing.';return}const link=new URL(location.href);link.searchParams.set('railFrom',item.from);link.searchParams.set('railTo',item.to);link.searchParams.set('railDate',item.date);link.searchParams.set('railTime',item.time);try{if(navigator.share)await navigator.share({title:'Lapan rail journey',url:link.href});else if(navigator.clipboard){await navigator.clipboard.writeText(link.href);$('railStatus').textContent='Journey link copied.'}else{$('railStatus').textContent=link.href}}catch(e){if(e.name!=='AbortError')$('railStatus').textContent='Could not share journey.'}};
$('railSwap').onclick=()=>{const a=$('origin').value;$('origin').value=$('destination').value;$('destination').value=a};
const linkParams=new URL(location.href).searchParams;if(linkParams.has('railFrom')&&linkParams.has('railTo')){$('origin').value=linkParams.get('railFrom').slice(0,100);$('destination').value=linkParams.get('railTo').slice(0,100);if(/^\d{4}-\d{2}-\d{2}$/.test(linkParams.get('railDate')||''))$('railDate').value=linkParams.get('railDate');if(/^\d{2}:\d{2}$/.test(linkParams.get('railTime')||''))$('railTime').value=linkParams.get('railTime');setTimeout(()=>mode(true),0)}
renderFavorites();
const stationCacheKey='lapan.rail.stations.v1';
let stationDirectory=[];try{const cached=JSON.parse(localStorage.getItem(stationCacheKey)||'null');if(cached&&Date.now()-cached.at<7*86400000)stationDirectory=cached.stations||[]}catch{}
function fillSuggestions(input){const list=$('railStationSuggestions');list.replaceChildren();const q=input.value.toLowerCase().trim();if(q.length<2)return;stationDirectory.filter(x=>x.name.toLowerCase().includes(q)).slice(0,35).forEach(s=>{const o=document.createElement('option');o.value=s.name;list.append(o)})}
for(const id of ['origin','destination']){const input=$(id);input.setAttribute('list','railStationSuggestions');input.addEventListener('input',()=>fillSuggestions(input))}
fetch('/api/rail/stations').then(r=>r.ok?r.json():null).then(d=>{if(!d?.stations)return;stationDirectory=d.stations;try{localStorage.setItem(stationCacheKey,JSON.stringify({at:Date.now(),stations:stationDirectory}))}catch{}}).catch(()=>{});
$('railNearby').onclick=()=>{const out=$('railNearbyResults');out.textContent='Checking nearby stations…';if(!navigator.geolocation){out.textContent='Location is unavailable in this browser.';return}navigator.geolocation.getCurrentPosition(async p=>{try{const q=new URLSearchParams({lat:String(p.coords.latitude),lon:String(p.coords.longitude)});const r=await fetch('/api/rail/stations?'+q),d=await r.json();if(!r.ok)throw Error(d.error||'Station lookup unavailable');out.replaceChildren();d.stations.forEach(s=>{const b=document.createElement('button');b.type='button';b.className='link';b.textContent=s.name+' · '+(s.distanceMeters/1000).toFixed(1)+' km straight-line';b.onclick=()=>{$('origin').value=s.name;out.replaceChildren()};out.append(b)})}catch(e){out.textContent=e.message}},()=>{out.textContent='Location permission denied or unavailable.'},{enableHighAccuracy:false,timeout:10000,maximumAge:60000})};

const today=new Date(),date=$('railDate');if(!date.value)date.value=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');
function mode(on){active=on;$('railPanel').hidden=!on;$('roadMode').setAttribute('aria-pressed',String(!on));$('railMode').setAttribute('aria-pressed',String(on));$('plan').hidden=on;$('refreshRoute').hidden=on||!document.body.classList.contains('has-route');if(on){$('journeytitle').textContent='Plan a rail journey';$('status').textContent='Enter station names above, then choose your travel date and time.'}else{$('journeytitle').textContent='Where are we going?'}}
$('roadMode').onclick=()=>mode(false);$('railMode').onclick=()=>mode(true);
function clear(){if(layer&&window.LapanMap){window.LapanMap.removeLayer(layer);layer=null}}
function stationNames(j){return j.legs.map((l,i)=>`${i+1}. ${l.line} · ${l.departure}–${l.arrival} · ${l.stops.length} stops`).join('\n')}
$('railPlan').onclick=async()=>{
 const from=$('origin').value.trim(),to=$('destination').value.trim(),date=$('railDate').value,time=$('railTime').value;
 if(!from||!to){$('railStatus').textContent='Enter both station names in the From and To fields.';return}
 $('railPlan').disabled=true;$('railStatus').textContent='Downloading and processing official rail timetables…';$('railResults').replaceChildren();clear();
 try{
  const qs=new URLSearchParams({from,to,date,time}),r=await fetch('/api/rail?'+qs),data=await r.json();
  if(!r.ok)throw Error(data.error||'Rail planning failed');
  $('railStatus').textContent=`${data.journeys.length} scheduled option(s) · Data checked ${new Date(data.checkedAt).toLocaleTimeString()}`;
  lastJourneys=[...data.journeys];
  lastJourneys.sort((a,b)=>$('railPreference').value==='fewest'?a.transfers-b.transfers||a.arrival.localeCompare(b.arrival):a.arrival.localeCompare(b.arrival)||a.transfers-b.transfers);
  lastJourneys.forEach((j,index)=>{
   const card=document.createElement('article');card.className='rail-result';
   const title=document.createElement('strong');title.textContent=`${j.departure} → ${j.arrival}`;
   const meta=document.createElement('small');meta.textContent=`${j.from} to ${j.to} · ${j.transfers} transfer(s) · ${j.agency}`;
   card.append(title,meta);
   j.legs.forEach((leg,i)=>{const row=document.createElement('div');row.className='rail-leg';const names=leg.stops.map(s=>s.name);row.textContent=`${leg.line}: ${names[0]} → ${names.at(-1)} (${leg.departure}–${leg.arrival})`;card.append(row);if(i<j.legs.length-1){const transfer=document.createElement('small');transfer.textContent=`Change trains at ${names.at(-1)}. Confirm platform and walking connection at the station.`;card.append(transfer)}});
   const fare=document.createElement('small');fare.textContent=j.fare==null?j.fareNote:`Estimated fare: RM ${Number(j.fare).toFixed(2)}`;card.append(fare);
   const show=document.createElement('button');show.type='button';show.className='link';show.textContent='Show this rail route on map';show.onclick=()=>{clear();if(window.LapanMap&&j.geometry?.coordinates?.length>1){layer=L.polyline(j.geometry.coordinates.map(p=>[p[1],p[0]]),{color:'#1677d2',weight:6,opacity:.9}).addTo(window.LapanMap);window.LapanMap.fitBounds(layer.getBounds(),{padding:[45,45]})}};card.append(show);$('railResults').append(card);
   if(index===0)show.click();
  });
 }catch(e){$('railStatus').textContent=e.message||'Rail timetable unavailable. Try again later.'}
 finally{$('railPlan').disabled=false}
};
})();
